    function maskS2Clouds(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
            .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000)
            .select("B.*")
            .copyProperties(image, ["system:time_start"]);
    }

    // Function to add NDVI band to an image.
    function addNDVI(image) {
        const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
        return image.addBands(ndvi);
    }

    // Function to get a processed mosaic for a given time period.
    const getProcessedMosaic = function(period) {
        return ee.ImageCollection(S2_COLLECTION)
            .filterBounds(aoi)
            .filterDate(period.start, period.end)
            .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', CLOUD_FILTER))
            .map(maskS2Clouds)
            .map(addNDVI)
            .median(); // Use median to create a single cloud-free composite.
